import React, { useEffect, useState } from "react";
import { apiDelete, apiGet } from "../utils/api.js";
import PersonTable from "./PersonTable.js";
import PersonFilter from "./PersonFilter.js";
import Pagination from "../components/Pagination.js";
import { Link } from "react-router-dom";

const PersonIndex = () => {
    const [persons, setPersons] = useState([]);
    const [filter, setFilter] = useState({ limit: 10, page: 0 });
    const [totalCount, setTotalCount] = useState(0);

    const fetchPersons = async () => {
        const query = new URLSearchParams(filter).toString();
        const endpoint = `/api/persons?${query}`;
        const data = await apiGet(endpoint);
        setPersons(data);
    };

    const fetchPersonCount = async () => {
        const query = new URLSearchParams(filter).toString();
        const data = await apiGet(`/api/persons/count?${query}`);
        setTotalCount(data.count);
    };

    useEffect(() => {
        fetchPersons();
        fetchPersonCount();
    }, [filter]);

    const deletePerson = async (id) => {
        try {
            await apiDelete(`/api/persons/${id}`);
            setPersons(persons.filter((item) => item._id !== id));
        } catch (error) {
            console.error(error.message);
            alert(error.message);
        }
    };

    const handleFilterChange = (e) => {
        const { name, value } = e.target;
        setFilter((prev) => {
            const newFilter = { ...prev, [name]: value };
            if (value === "false") {
                delete newFilter[name];
            }
            return newFilter;
        });
    };

    return (
        <div>
            <h1>Seznam osob</h1>
            <PersonFilter filter={filter}  handleChange={handleFilterChange} />
            <PersonTable deletePerson={deletePerson} items={persons} filter={filter} label="" />
            <Pagination filter={filter} setFilter={setFilter} totalCount={totalCount} />
            <Link to={"/persons/create"} className="btn btn-success mt-3 person-button">
                Nová osoba
            </Link>
        </div>
    );
};

export default PersonIndex;
